class Solution {
public:
    struct State { int s0, s1, s2; };
    int INF = 1000000;

    State dfs(TreeNode* node) {
        if (!node) return {0, 0, INF};
        State l = dfs(node->left);
        State r = dfs(node->right);
        int s0 = l.s1 + r.s1;
        int s1 = min(l.s2 + min(r.s1, r.s2), r.s2 + min(l.s1, l.s2));
        int s2 = 1 + min({l.s0, l.s1, l.s2}) + min({r.s0, r.s1, r.s2});
        return {s0, s1, s2};
    }

    int minCameraCover(TreeNode* root) {
        State s = dfs(root);
        return min(s.s1, s.s2);
    }
};
